/**
 * Panorama PhotoDome chunk — CODE-SPLIT.
 *
 * This is a REGISTERED CHUNK MANIFEST MODULE (see MANIFEST_MODULES in
 * tooling/check-shader-imports.mjs, `chunk: true`) — the ONLY legal import site
 * for `PhotoDome`, its `BackgroundMaterial` shaders, and
 * `EquiRectangularCubeTexture`. It is loaded EXCLUSIVELY via dynamic `import()`
 * from applyEnvironment.ts, ONLY when a world's background is a `panorama`
 * (lint rule 3: a static import of this module anywhere would pull
 * BackgroundMaterial into the main bundle and blow the bundle budget — a
 * color-only world never pays for it; the e2e asserts both directions).
 *
 * MISSING SHADERS FAIL SILENTLY HERE. `PhotoDome`
 * materializes a `BackgroundMaterial`, and tree-shaken Babylon does NOT bundle
 * its GLSL shaders — without the side-effect imports below the failure is the
 * blank-screen / `VERTEX SHADER ERROR: '<' : syntax error` (the shader XHR gets
 * index.html) / `.vite/deps/background.fragment-*.js` 404 class, which e2e
 * CANNOT red-green (headless passes by luck via warm caches). Every shader
 * specifier here is mirrored in `optimizeDeps.include` in vite.config.ts;
 * `npm run lint` fails when they drift.
 *
 * PhotoDome creates MULTIPLE meshes (the main dome mesh AND an unnamed
 * backdrop). ALL are set `isPickable=false` here (backdrops must not be
 * pickable), and the dome is NEVER registered with the
 * EntityRegistry, so it is non-walkable BY CONSTRUCTION (`walkableMeshes()`
 * returns registry-owned meshes only; the grounding probe filters to that set
 * — the "stuck at y=500 on the PhotoDome" bug cannot recur).
 */

// BackgroundMaterial (PhotoDome) — GLSL (WebGL2 floor, always loaded).
import '@babylonjs/core/Shaders/background.vertex';
import '@babylonjs/core/Shaders/background.fragment';

import { PhotoDome } from '@babylonjs/core/Helpers/photoDome';
import { log } from '../../logging/runtimeLog';
import { EquiRectangularCubeTexture } from '@babylonjs/core/Materials/Textures/equiRectangularCubeTexture';
import type { Scene } from '@babylonjs/core/scene';
import { WORLD_SKY, fetchedUrl, isHeld } from '../../net/worldRequests';
import { isExrPanorama, isHdrPanorama } from './panoramaKind';

/**
 * BackgroundMaterial — WGSL (WebGPU path). Capability-gated exactly like
 * `loadWebGPUPbrShaders` in gltfChunk.ts: WGSL is dead weight on the WebGL2
 * floor, so it stays a nested dynamic import awaited only when the session's
 * engine is WebGPU.
 */
export async function loadWebGPUBackgroundShaders(): Promise<void> {
  await Promise.all([
    import('@babylonjs/core/ShadersWGSL/background.vertex'),
    import('@babylonjs/core/ShadersWGSL/background.fragment'),
  ]);
}

/** The engine's number for a texture whose rows repeat past its edge (its `WRAP_ADDRESSMODE`). */
const WRAP_REPEAT = 1;
/** The engine's number for reading a texture from its nearest pixel, unsmoothed (its `NEAREST_SAMPLINGMODE`). */
const SAMPLE_NEAREST = 1;
/** IBL cube resolution derived from the equirect panorama (small; ambient). */
const IBL_SIZE = 128;
/**
 * The dome's diameter as a share of the camera's range. The dome follows the
 * camera, so its radius is how far the world may reach before the sky is
 * drawn in front of it; just under half the range keeps it inside the far plane.
 */
const DOME_SHARE_OF_RANGE = 0.9;
/** The diameter when there is no camera yet to measure. */
const DOME_SIZE_NO_CAMERA = 9000;

export interface PanoramaDomeHandle {
  /**
   * True when the sky-derived IBL is `scene.environmentTexture`, or will be
   * once the picture's bytes arrive. False on devices without float linear filtering (see createPanoramaDome) —
   * the caller then supplies the neutral IBL so PBR materials stay lit.
   */
  iblApplied: boolean;
  /** Set isPickable=false on the dome mesh AND every descendant mesh. */
  setPickableFalse(): void;
  /** Dispose the dome (meshes + material + its textures) AND the IBL texture,
   * and clear `scene.environmentTexture` (churn-safe on a reused scene). */
  dispose(): void;
}

/**
 * Build an equirectangular PhotoDome for the visible sky + an
 * `EquiRectangularCubeTexture` as `scene.environmentTexture` for the
 * skybox-derived IBL that lights PBR materials.
 *
 * Babylon is never given the picture's address to fetch: the browser would
 * ask for it with the page's cookies. The dome stands at once with an empty
 * texture, the bytes are fetched once under the world's rules, and both
 * textures are pointed at them when they arrive, so a large sky never holds
 * up the world. A picture that cannot be had leaves the dome without one.
 */
export async function createPanoramaDome(
  resolvedUrl: string,
  scene: Scene,
  engineKind?: string,
): Promise<PanoramaDomeHandle> {
  if (engineKind === 'webgpu') {
    await loadWebGPUBackgroundShaders();
  }

  // useDirectMapping: TRUE — the equirect image is sampled through the dome
  // sphere's own UVs. The reflection-mapped path (false) routes
  // BackgroundMaterial through a reflection-matrix branch whose WGSL does not
  // compile on WebGPU ("no matching constructor for 'mat3x3<f32>(mat4x4<f32>)'"
  // — GLSL allows that narrowing, WGSL does not), which invalidates the vertex
  // ShaderModule, then the render pipeline, then the whole command buffer: the
  // canvas goes BLACK. Verified on real Chrome + WebGPU; direct mapping is the
  // standard equirect photo-dome path and renders identically.
  const dome = new PhotoDome(
    'panoramaDome',
    isHeld(resolvedUrl) ? resolvedUrl : '',
    { size: scene.activeCamera ? scene.activeCamera.maxZ * DOME_SHARE_OF_RANGE : DOME_SIZE_NO_CAMERA, useDirectMapping: true },
    scene,
  );
  // The sky stays centred on the visitor, however far they go.
  dome.mesh.infiniteDistance = true;
  // The engine hands an OpenEXR image over with its rows the other way up from
  // every other kind (seen on the built page: the same panorama as a PNG and as
  // a Radiance file is upright, as an EXR the ground is overhead), so it is
  // turned back here.
  // Turned by reading it from the other end, which needs its rows to
  // repeat: held at the edge, as the dome's texture is, every row past the
  // first reads as the edge and the sky is black.
  if (isExrPanorama(resolvedUrl)) {
    dome.texture.wrapV = WRAP_REPEAT;
    dome.texture.vScale = -1;
  } else if (isHdrPanorama(resolvedUrl) && !scene.getEngine().getCaps().textureFloatLinearFiltering) {
    // A Radiance image is held as full floats, which some devices cannot
    // blend between pixels; asked to, WebGPU refuses the draw and the sky is
    // black. There it is drawn from the nearest pixel instead: blockier, and
    // there.
    dome.texture.updateSamplingMode(SAMPLE_NEAREST);
    log.warn('[webverse] panorama: this device cannot smooth a float image, so the high-dynamic-range sky is drawn unsmoothed.');
  }

  // Skybox-derived IBL: an equirect→cube env texture the PBR pipeline
  // samples, so the panorama lights the world it surrounds.
  //
  // CAPABILITY GATE (WebGPU): EquiRectangularCubeTexture
  // builds a FLOAT raw cube. Where float LINEAR FILTERING is unsupported —
  // reported on WebGPU/D3D12 — Babylon force-disables its mipmaps, and the PBR
  // reflection path then requests mip level 1 on a 1-mip texture. WebGPU
  // rejects that view EVERY FRAME (GPUValidationError) and the canvas goes
  // BLACK. Detected by capability, never by engine name: the same GPU is fine
  // under WebGL2, and a WebGPU device that CAN filter floats keeps the
  // sky-derived IBL. Without it, the caller supplies the neutral IBL — the
  // visible sky dome (an ordinary 2D texture) is unaffected either way.
  //
  // A high-dynamic-range image is drawn as the sky by the dome above, whose
  // texture the engine reads by the file's kind. The cube reads its image as a
  // picture and cannot read this one, so the world is lit by the neutral
  // environment the caller supplies.
  const hdr = isHdrPanorama(resolvedUrl);
  const floats = scene.getEngine().getCaps().textureFloatLinearFiltering;
  const wantsIbl = !hdr && floats;
  let iblTexture: EquiRectangularCubeTexture | null = null;
  const lightFrom = (address: string): void => {
    iblTexture = new EquiRectangularCubeTexture(address, scene, IBL_SIZE);
    // The world's own sky: a glb that finishes loading meanwhile must not take it for its own and remove it.
    iblTexture.metadata = { [WORLD_SKY]: true };
    scene.environmentTexture = iblTexture;
  };
  if (!hdr && !floats) {
    log.warn(
      '[webverse] panorama IBL skipped: this device cannot linearly filter float ' +
        'textures, and the equirect env cube would render black. The sky dome is ' +
        'unaffected; PBR reflections fall back to the neutral environment.',
    );
  }
  // The object URL the picture's bytes are held under; '' once the dome is gone.
  let held: string | undefined;
  if (isHeld(resolvedUrl)) {
    if (wantsIbl) lightFrom(resolvedUrl);
  } else {
    fetchedUrl(scene, resolvedUrl).then(
      (address) => {
        if (held === '') return URL.revokeObjectURL(address);
        held = address;
        // The held bytes' address says nothing of their kind, so the engine is told it, as the file's name told it.
        dome.texture.updateURL(address, undefined, undefined, isExrPanorama(resolvedUrl) ? '.exr' : hdr ? '.hdr' : undefined);
        if (wantsIbl) lightFrom(address);
      },
      (err) => {
        // Drawn without its picture, and not waited for.
        dome.texture.isBlocking = false;
        log.warn(`[webverse] panorama failed to load ${resolvedUrl}: ${err instanceof Error ? err.message : String(err)}`);
      },
    );
  }

  return {
    iblApplied: wantsIbl,
    setPickableFalse(): void {
      const meshes = [dome.mesh, ...dome.mesh.getChildMeshes(false)];
      for (const mesh of meshes) mesh.isPickable = false;
    },
    dispose(): void {
      if (held) URL.revokeObjectURL(held);
      held = '';
      if (iblTexture !== null && scene.environmentTexture === iblTexture) {
        scene.environmentTexture = null;
      }
      iblTexture?.dispose();
      // disposeMaterialAndTextures=true → release the BackgroundMaterial + the
      // dome's own equirect texture (churn-critical on a reused scene).
      dome.dispose(false, true);
    },
  };
}

/** The module shape applyEnvironment consumes (injectable for unit tests). */
export type PanoramaDomeModule = {
  createPanoramaDome: typeof createPanoramaDome;
};
