/**
 * What kind of image a panorama is, told by its address: a picture (PNG,
 * JPEG and the like), or a high-dynamic-range image whose values go above
 * white, as Radiance (`.hdr`) or OpenEXR (`.exr`) files hold. Pure: no engine.
 */

/** The address's path, without a query or fragment; the address itself where it is not one a URL can be made of. */
function pathOf(url: string): string {
  try {
    return new URL(url).pathname;
  } catch {
    return url.split(/[?#]/)[0] ?? url;
  }
}

/** Whether the address names a high-dynamic-range image, by its path's extension; a query or fragment does not count. */
export function isHdrPanorama(url: string): boolean {
  return /\.(hdr|exr)$/i.test(pathOf(url));
}

/** Whether the address names an OpenEXR image. */
export function isExrPanorama(url: string): boolean {
  return /\.exr$/i.test(pathOf(url));
}
